static char *get_size_str(char *size_str, size_t size)
{
	if(size % 1024){
		sprintf(size_str, "%6d  B", size);
	}else{
		size /= 1024;		//k
		if(size % 1024){
			sprintf(size_str, "%6d KB", size);
		}else{
			size /= 1024; //m
			sprintf(size_str, "%6d MB", size);
		}
	}

	return size_str;
}

static void int2char(unsigned char *data, int a)
{
	data[0]  = (a & 0xFF000000) >> 24;
	data[1]  = (a & 0x00FF0000) >> 16;
	data[2]  = (a & 0x0000FF00) >>  8;
	data[3]  = (a & 0x000000FF) >>  0;
}

static void int16tochar(uint8_t *data, uint16_t a)
{
	data[0]  = (a & 0xFF00) >> 8;
	data[1]  = (a & 0x00FF) >> 0;
}

static int char2int(unsigned char *data)
{
	return (data[0] << 24) + (data[1] << 16) + (data[2]  << 8) + data[3] ;
}

static int char2int16(uint8_t *data)
{
	return (data[0]  << 8) + data[1];
}

char *get_fstype(int type)
{
	switch (type) {
		case RAW:    return "raw"     ;
		case CRAMFS: return "cramfs"  ;
		case ROMFS:  return "romfs"   ;
		case JFFS2:  return "jffs2"   ;
		case YAFFS2: return "yaffs2"  ;
		case MINIFS: return "minifs"  ;
		case SQUASHFS: return "squashfs"  ;
		case UBIFS:  return "ubifs"  ;
		case HIDE:   return "hide"    ;
		default:     return "unknown" ;
	}
}

static char *id2str(char id) {
	static char buf[5] = {0, };

	if (id == 0xFF)
		strcpy(buf, "   ");
	else
		sprintf(buf, "%-3d", id);

	return buf;
}

static char *crc32str(unsigned int crc)
{
	static char buf[9] = {0, };

	if (crc == 0)
		memset(buf, ' ', 8);
	else
		sprintf(buf, "%08X", crc);

	return buf;
}

void partition_printf(void)
{
	int i;
	char size_str1[32], size_str2[32], size_str3[32], size_str4[32];
	int num;
	struct partition *flash_entry;

	num = flash_get_type();
	flash_entry = flash_entry_arr[num];

	gxlogi("Partition Version :  %d\n", flash_entry->version);
	gxlogi("Partition Count   :  %d\n", flash_entry->count);
	gxlogi("Write Protect     :  %s\n", flash_entry->write_protect ? "TRUE": "FALSE");
	gxlogi("CRC32 Enable      :  %s\n", flash_entry->crc32_enable ? "TRUE": "FALSE");
	gxlogi("Table CRC32       :  %X\n", flash_entry->crc_verify);

	gxlogi("==============================================================================================\n");
	gxlogi("%-3s%-8s%-8s%-10s%-9s%10s%12s%11s%10s%10s\n", "ID", "NAME", "FS", "CRC32", "START", "TOTAL_SIZE", "MAIN_SIZE", "USED_SIZE", "Use%", "RES_SIZE");
	gxlogi("==============================================================================================\n");
	for (i=0; i < flash_entry->count; i++) {
		gxlogi("%s%-8s%-8s%-10s%08x%11s%11s%11s%8d%%%11s\n",
				id2str(flash_entry->tables[i].mtd_id),
				flash_entry->tables[i].name,
				get_fstype(flash_entry->tables[i].file_system_type),
				crc32str(flash_entry->tables[i].crc_verify),
				flash_entry->tables[i].start_addr,
				get_size_str(size_str1, flash_entry->tables[i].total_size),
				get_size_str(size_str2, flash_entry->tables[i].partition_size),
				get_size_str(size_str3, flash_entry->tables[i].used_size),
				flash_entry->tables[i].partition_size > 0 ? flash_entry->tables[i].used_size * 100 / flash_entry->tables[i].partition_size : 0,
				get_size_str(size_str4, flash_entry->tables[i].reserved_size)
		      );
	}
	gxlogi("----------------------------------------------------------------------------------------------\n\n");
}

void all_partition_printf(void)
{
	int i;
	char map[FLASH_TYPE_NUM];
	int type;

	type = flash_get_type();
	flash_get_used_device_map(map);

	for (i = 0; i < FLASH_TYPE_NUM; i++) {
		if (map[i] == 1) {
			flash_switch_type(i);
			partition_printf();
		}
	}
	// recover flash device
	flash_switch_type(type);
}

static int calc_table_crc(struct partition *tbl)
{
	return crc32(0, (unsigned char *)tbl, sizeof(struct partition) - 4);
}

static int check_table_crc(struct partition *tbl, unsigned char *data, int len)
{
	unsigned int new_crc;

	if (tbl->version >= PARTITION_VERSION) {
		new_crc = crc32(0, data, len - 4);
		if(new_crc != tbl->crc_verify)
			return -1;
		else
			return 0;
	}

	return -1;
}

static int table_read(struct partition *tbl, unsigned char *data, int len)
{
	int ret = -1;
	int i, mtd_id = 0;
	unsigned char *part;
	unsigned char *crc32_table = data + FLASH_PARTITION_CRC_ADDR;
	unsigned char *part_version = data + FLASH_PARTITION_VERSION_ADDR;
	if (len < FLASH_PARTITION_SIZE)
		return -1;

	memset(tbl, 0, sizeof(struct partition));  // read table

	tbl->magic = char2int(data);
	tbl->count = data[4];
	tbl->crc_verify = char2int(data + FLASH_PARTITION_SIZE - 4);
	tbl->version = data[FLASH_PARTITION_SIZE - 5];
	tbl->crc32_enable = data[FLASH_PARTITION_SIZE - 6];
	tbl->write_protect = data[FLASH_PARTITION_SIZE - 7];

	if (tbl->count > FLASH_PARTITION_NUM) {
		gxlogi("%s,%d partition_num=%d error\n", __func__, __LINE__, tbl->count);

		return -1;
	}

	part = data + 5;
	for (i = 0; i < tbl->count; i++, part += FLASH_PARTITION_HEAD_SIZE) {
		memset(tbl->tables[i].name, 0x00, sizeof(tbl->tables[i].name));
		memcpy(tbl->tables[i].name, part, FLASH_PARTITION_V1_NAME_SIZE);
		tbl->tables[i].total_size       = char2int(part +  8);
		tbl->tables[i].used_size        = char2int(part + 12);
		tbl->tables[i].partition_size   = tbl->tables[i].total_size;
		tbl->tables[i].start_addr       = char2int(part + 16);
		tbl->tables[i].file_system_type = part[20];
		tbl->tables[i].mode             = part[21] & 0x7F;
		tbl->tables[i].crc32_enable     = part[21] >> 7;
		if (tbl->version >= PARTITION_VERSION) {
			tbl->tables[i].id               = part[22] & 0x7F;
			tbl->tables[i].write_protect    = (part[22] >> 7) & 0x01;
		}
		else {
			tbl->tables[i].id               = i;
			tbl->tables[i].write_protect    = 0;
		}
		tbl->tables[i].update_tags = part[23] & 0x03;
		tbl->tables[i].crc_verify = char2int(crc32_table + i * 4);
		tbl->tables[i].version = char2int16(part_version + i * 2);

		if (tbl->tables[i].file_system_type != HIDE)
			tbl->tables[i].mtd_id = mtd_id++;
		else
			tbl->tables[i].mtd_id = 0xFF;
	}

	/* huangjb:must be confrim */
	ret = check_table_crc(tbl, data, len);

	return ret;
}

static int table_write(struct partition *tbl, unsigned char *data, int len)
{
	int i;
	unsigned char *part;
	unsigned char *crc32_table = data + FLASH_PARTITION_CRC_ADDR;
	unsigned char *part_version = data + FLASH_PARTITION_VERSION_ADDR;

	if (tbl == NULL || len < FLASH_PARTITION_SIZE)
		return -1;

	//	memcpy(data, tbl, FLASH_PARTITION_SIZE);  // read table
	memset(data, 0xFF, FLASH_PARTITION_SIZE);  // read table
	int2char(data, tbl->magic);
	data[4] = tbl->count;

	part = data + 5;
	for (i = 0; i < tbl->count; i++, part+= FLASH_PARTITION_HEAD_SIZE) {
		memcpy(part, tbl->tables[i].name, FLASH_PARTITION_V1_NAME_SIZE + 1);
		int2char(part +  8, tbl->tables[i].total_size);
		int2char(part + 12, tbl->tables[i].used_size);
		int2char(part + 16, tbl->tables[i].start_addr);
		part[20] = tbl->tables[i].file_system_type;
		part[21] = tbl->tables[i].mode | (tbl->tables[i].crc32_enable  << 7);
		part[22] = tbl->tables[i].id   | (tbl->tables[i].write_protect << 7);
		part[23] = tbl->tables[i].update_tags & 0x03;
		int2char(crc32_table + i * 4, tbl->tables[i].crc_verify);
		int16tochar(part_version + i * 2, tbl->tables[i].version);
	}

	for (; i < FLASH_PARTITION_NUM; i++, part += FLASH_PARTITION_HEAD_SIZE) {
		memset(part, 0xFF, FLASH_PARTITION_HEAD_SIZE);
		int2char(crc32_table + i * 4, 0xFFFFFFFF);
	}

	data[FLASH_PARTITION_SIZE - 5] = tbl->version;
	data[FLASH_PARTITION_SIZE - 6] = tbl->crc32_enable;
	data[FLASH_PARTITION_SIZE - 7] = tbl->write_protect;

	tbl->crc_verify = crc32(0, data, FLASH_PARTITION_SIZE - 4);
	int2char(data + FLASH_PARTITION_SIZE - 4, tbl->crc_verify);

	return 0;
}

